{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A massive iron gate hangs askew, covered in rust and old royal banners. The glass diver stands before it, helmet reflecting the shattered towers beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unrolls a worn map under a broken arch.",
      "visual_description": "Under a crumbling stone arch, Mara spreads a parchment map across a fallen pillar, compass glinting as she traces a route through the ruins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers to life inside a collapsed hall.",
      "visual_description": "Inside a roofless hall, the oracle lamp sits on a slab of marble, its single flame-eye casting eerie shadows across shattered columns.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through rubble and broken glass.",
      "visual_description": "The tin fox picks its way over debris, key-wind tail ticking, blue eyes scanning a street lined with faded banners and empty doorways.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver swims through a cracked mirror in an abandoned courtyard.",
      "visual_description": "In a courtyard full of shattered mirrors, the glass diver steps through a tall, jagged pane, coat rippling as he emerges into a hidden passage.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a cursed tower on her map while the oracle lamp warns of danger.",
      "visual_description": "Mara pencils a spiral onto her map near a sketch of a twisted tower, while the oracle lamp's flame-eye narrows and casts a red glow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The sleeping tax collector snores on a stack of ledgers inside a looted treasury.",
      "visual_description": "In a ransacked treasury, the sleeping tax collector lies atop a pile of stamp-paper and ledgers, one hand clutching a quill, oblivious to the chaos.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox discovers a trapdoor hidden under a fallen banner.",
      "visual_description": "The tin fox nudges aside a heavy royal banner embroidered with faded crests, revealing a rusty ring set into a stone trapdoor.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver descends into a moonlit crypt beneath the city.",
      "visual_description": "The glass diver climbs down a ladder into a vaulted crypt, where pale light from a ceiling crack illuminates rows of empty stone sarcophagi.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara and the oracle lamp consult a broken statue for directions.",
      "visual_description": "Mara brushes moss from a headless statue's pedestal, while the oracle lamp hovers nearby, its flame-eye reflecting the carved inscriptions.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes briefly to stamp a useless permit.",
      "visual_description": "Half-asleep, the tax collector sits up, stamps a blank parchment with a clatter, then slumps back onto his ledger pillow, snoring.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox leads the group through a maze of collapsed market stalls.",
      "visual_description": "The tin fox weaves between toppled wooden stalls and scattered pottery, its blue eyes guiding the glass diver and Mara through the labyrinth.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door appears in a wall of ivy, glowing with runes.",
      "visual_description": "An arched door of pale stone, covered in glowing runes, emerges from a curtain of hanging ivy. The oracle lamp's flame-eye reads the symbols silently.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara unlocks the magic door using a key drawn on her map.",
      "visual_description": "Mara tears a key-shaped corner from her map and presses it into a recess in the door, which shimmers and swings open with a grinding sound.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The group crosses a grand hall filled with stained glass and faded tapestries.",
      "visual_description": "A long hall with a shattered stained-glass ceiling; the glass diver's helmet reflects broken colors as they walk past tapestries of forgotten battles.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols of animated statues block the exit tower.",
      "visual_description": "At the base of a tower, four life-sized stone statues in rusted armor move with jerky steps, their visors glowing with faint blue light.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver distracts the statues while Mara and the tin fox run for the bridge.",
      "visual_description": "The glass diver leaps onto a balcony, shattering a stained-glass window to draw the statues' attention, as Mara and the tin fox sprint toward a stone bridge.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge as the city crumbles behind them.",
      "visual_description": "The glass diver, Mara, and the tin fox race across a narrow bridge over a dry moat, the towers of the city collapsing in a cloud of dust and stone behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    }
  ]
}

